package com.kobayami.graphity.benchmarks.controlflow;

import com.kobayami.graphity.Graph;
import com.kobayami.graphity.testutils.ControlFlowGraphs;

/**
 * Control-flow shapes for the benchmarks of the control-flow analyses, generated by
 * {@link ControlFlowGraphs}. Node 0 is the entry of every graph.
 */
public enum ControlFlowShape {
  /** Structured code with nested loops, reducible throughout. */
  STRUCTURED,
  /** Structured code with one random jump per hundred nodes, mostly irreducible. */
  IRREDUCIBLE,
  /** A ladder of branches: the dominance frontier relation grows quadratically. */
  LADDER,
  /** A straight-line chain: the deepest possible dominator tree. */
  CHAIN,
  /** A fan behind a chain: quadratic for plain SEMI-NCA and the iterative algorithm. */
  FAN_BEHIND_CHAIN,
  /**
   * Many small structured graphs of 10 to 200 nodes, together {@code nodeCount}: the size of
   * real methods, where fixed costs and allocation weigh more than the algorithm.
   */
  SMALL_METHODS;

  /** One graph of about {@code nodeCount} nodes; not defined for {@link #SMALL_METHODS}. */
  public Graph generate(int nodeCount, long seed) {
    return switch (this) {
      case STRUCTURED -> ControlFlowGraphs.structured(nodeCount, seed);
      case IRREDUCIBLE -> ControlFlowGraphs.irreducible(nodeCount, Math.max(1, nodeCount / 100), seed);
      case LADDER -> ControlFlowGraphs.ladder(nodeCount / 2);
      case CHAIN -> ControlFlowGraphs.chain(nodeCount);
      case FAN_BEHIND_CHAIN -> ControlFlowGraphs.fanBehindChain(nodeCount / 2, nodeCount - nodeCount / 2 - 1);
      case SMALL_METHODS -> throw new UnsupportedOperationException("use generateAll");
    };
  }

  /** The graphs of this shape with about {@code nodeCount} nodes together. */
  public Graph[] generateAll(int nodeCount, long seed) {
    if (this != SMALL_METHODS) return new Graph[] {generate(nodeCount, seed)};
    var rnd = new java.util.Random(seed);
    var graphs = new java.util.ArrayList<Graph>();
    int total = 0;
    while (total < nodeCount) {
      var graph = ControlFlowGraphs.structured(10 + rnd.nextInt(191), rnd.nextLong());
      graphs.add(graph);
      total += graph.nodeCount();
    }
    return graphs.toArray(new Graph[0]);
  }
}
